#[verifier::spec]
pub fn direct_subclass(a: NumpyTypeClass, b: NumpyTypeClass) -> bool {
    // Reflexivity
    if a == b {
        return true;
    }
    // The eight integer‐leaf → IntegerType relations
    match (a, b) {
        (NumpyTypeClass::Int8Type,  NumpyTypeClass::IntegerType)
      | (NumpyTypeClass::Int16Type, NumpyTypeClass::IntegerType)
      | (NumpyTypeClass::Int32Type, NumpyTypeClass::IntegerType)
      | (NumpyTypeClass::Int64Type, NumpyTypeClass::IntegerType)
      | (NumpyTypeClass::UInt8Type,  NumpyTypeClass::IntegerType)
      | (NumpyTypeClass::UInt16Type, NumpyTypeClass::IntegerType)
      | (NumpyTypeClass::UInt32Type, NumpyTypeClass::IntegerType)
      | (NumpyTypeClass::UInt64Type, NumpyTypeClass::IntegerType)
        => return true,
        _ => {}
    }
    // The two float‐leaf → FloatingType relations
    match (a, b) {
        (NumpyTypeClass::Float32Type, NumpyTypeClass::FloatingType)
      | (NumpyTypeClass::Float64Type, NumpyTypeClass::FloatingType)
        => return true,
        _ => {}
    }
    // The two complex‐leaf → ComplexType relations
    match (a, b) {
        (NumpyTypeClass::Complex64Type,  NumpyTypeClass::ComplexType)
      | (NumpyTypeClass::Complex128Type, NumpyTypeClass::ComplexType)
        => return true,
        _ => {}
    }
    // Mid‐level relations
    if a == NumpyTypeClass::IntegerType && b == NumpyTypeClass::NumberType {
        return true;
    }
    if a == NumpyTypeClass::FloatingType && (
           b == NumpyTypeClass::InexactType
        || b == NumpyTypeClass::NumberType
    ) {
        return true;
    }
    if a == NumpyTypeClass::ComplexType && (
           b == NumpyTypeClass::InexactType
        || b == NumpyTypeClass::NumberType
    ) {
        return true;
    }
    // Top‐level scalar relations
    if matches!(a, 
           NumpyTypeClass::NumberType
        |  NumpyTypeClass::BooleanType
        |  NumpyTypeClass::IntegerType
        |  NumpyTypeClass::FloatingType
        |  NumpyTypeClass::ComplexType
        |  NumpyTypeClass::InexactType
       )
       && b == NumpyTypeClass::ScalarType
    {
        return true;
    }
    // No other direct subclasses
    false
}

